<script setup>
import { ref,onMounted,onBeforeUnmount,watch } from 'vue'
import { api } from '../api'
import { storageKey,accountEpoch } from '../session'
import { useWorkflowWrite } from '../composables/useWorkflowWrite'
import PageHeader from './ui/PageHeader.vue'
const data=ref(null),answers=ref({}),sendGroups=ref([]),version=ref(0),error=ref(''),notice=ref(''),useAI=ref(false),ack=ref(false),preview=ref(null),dirty=ref(false),writes=useWorkflowWrite('questionnaire'),epoch=accountEpoch,key=storageKey('questionnaire-draft')
let ready=false,timer=null,alive=true
function cache(){if(!ready)return;dirty.value=true;localStorage.setItem(key,JSON.stringify({answers:answers.value,send_groups:sendGroups.value}));clearTimeout(timer);timer=setTimeout(save,900)}
watch([answers,sendGroups],cache,{deep:true})
async function load(){try{const result=await api.flow('/questionnaire');if(!alive||epoch!==accountEpoch)return;data.value=result;version.value=result.draft?.version||0;preview.value=result.draft?.preview;let cached=null;try{cached=JSON.parse(localStorage.getItem(key)||'null')}catch{};answers.value=cached?.answers||result.draft?.answers||{};sendGroups.value=cached?.send_groups||result.draft?.send_groups||[];ready=true;for(const q of result.questions)if(!answers.value[q.id])answers.value[q.id]={state:'answered',value:''}}catch(e){error.value=e.message}}
async function save(){if(writes.busy.value||!ready)return;const snapshot=JSON.stringify(writes.pending.value?{answers:writes.pending.value.body.answers,send_groups:writes.pending.value.body.send_groups}:{answers:answers.value,send_groups:sendGroups.value});try{const result=await writes.send('/questionnaire',{expected_version:version.value,answers:answers.value,send_groups:sendGroups.value},'PUT');version.value=result.version;preview.value=result.preview;if(snapshot===JSON.stringify({answers:answers.value,send_groups:sendGroups.value})){dirty.value=false;notice.value='问卷已保存；保存不会调用模型。'}else{clearTimeout(timer);timer=setTimeout(save,900)}error.value=''}catch(e){error.value=e.message}}
function skip(group){for(const q of data.value.questions.filter(q=>q.group===group))answers.value[q.id]={state:'skipped',value:''}}
async function generate(){await save();if(error.value||dirty.value)return;try{const result=await writes.send('/questionnaire/preview',{expected_version:version.value,use_ai:useAI.value,acknowledge_scope:ack.value});version.value=result.version;preview.value=result.preview}catch(e){error.value=e.message}}
async function confirm(){try{const result=await writes.send('/questionnaire/confirm',{expected_version:version.value});version.value=result.version;preview.value=null;notice.value='已确认。已有评估与启动资金只建立一次。';localStorage.removeItem(key);await load()}catch(e){error.value=e.message}}
onMounted(load);onBeforeUnmount(()=>{alive=false;clearTimeout(timer)})
</script>
<template><div class="reading-page"><PageHeader title="角色问卷与长期偏好" description="每题、整组都可跳过；保存不调用模型，暂离可恢复。"/><p v-if="error" class="error" role="alert">{{ error }} 你的本机答案仍保留。</p><p v-if="notice" role="status">{{ notice }}</p><p v-if="data?.onboarding_completed" class="muted">已有基线 {{ data.baseline_kind }}；本次只更新你明确授权的长期背景，不覆盖旧评估、不重发启动资金。</p><p v-if="data">进度 {{ Object.values(answers).filter(a=>a.state==='skipped'||a.value.trim()).length }}/{{ data.questions.length }} · {{ dirty?'本机有未同步修改':'已保存状态' }}</p><details v-for="group in data?.groups" :key="group.id" class="card"><summary>{{ group.title }}</summary><button class="btn" @click="skip(group.id)">跳过整组</button><label><input type="checkbox" v-model="sendGroups" :value="group.id"/>允许选定答案用于之后主动分析的背景（可撤回）</label><article v-for="q in data.questions.filter(q=>q.group===group.id)" :key="q.id"><label>{{ q.text }}<textarea v-if="answers[q.id]?.state!=='skipped'" v-model="answers[q.id].value" maxlength="2000" rows="2"/></label><button class="btn" @click="answers[q.id]=answers[q.id].state==='skipped'?{state:'answered',value:''}:{state:'skipped',value:''}">{{ answers[q.id]?.state==='skipped'?'已跳过 · 改为回答':'跳过这题' }}</button></article></details><details v-if="data?.legacy_state&&Object.keys(data.legacy_state).length" class="card"><summary>旧动态问卷作答（保留，不自动授权或覆盖）</summary><pre class="original-text">{{ JSON.stringify(data.legacy_state,null,2) }}</pre></details><section class="card"><button class="btn" :disabled="writes.busy.value" @click="save">{{ writes.pending.value?'恢复上次保存':'保存全部答案' }}</button><label><input type="checkbox" v-model="useAI"/>主动使用本人模型生成初始建议（可关闭）</label><label><input type="checkbox" v-model="ack"/>我同意发送选定组中已回答的内容，并在确认后更新这些背景</label><button class="btn" :disabled="writes.busy.value||(useAI&&!ack)" @click="generate">{{ data?.onboarding_completed?'预览未来背景更新':'生成建档预览' }}</button><div v-if="preview"><p>{{ preview.summary }}</p><ul><li v-for="attr in preview.attributes" :key="attr.name">{{ attr.name }} {{ attr.value }} · {{ attr.reason }}</li></ul><p>{{ data?.onboarding_completed?'已有资金保持不变':'启动资金：'+preview.initial_coins+' 币' }}</p><button class="btn primary" :disabled="writes.busy.value" @click="confirm">核对并确认</button></div></section></div></template>
